// Canvas app: add the "Environment Variable Definitions" and
// "Environment Variable Values" tables as data sources.

// App.Formulas (named formula, evaluated once and cached)
nfSupportEmail =
    With(
        {
            def: LookUp(
                'Environment Variable Definitions',
                'Schema Name' = "bv_SupportEmail"
            )
        },
        Coalesce(
            LookUp(
                'Environment Variable Values',
                'Environment Variable Definition'.'Environment Variable Definition' =
                    def.'Environment Variable Definition'
            ).Value,
            def.'Default Value'
        )
    );

