        Coalesce(varSelectedRequest, Defaults(Requests)),
        {
            // Text
            Name: txtTitle.Text,

            // Lookup: pass the whole related record
            Customer: cmbCustomer.Selected,

            // Lookup when you only have the GUID
            'Assigned To': LookUp(Users, User = GUID(varUserId)),

            // Choice (single): use the enum, not text
            Priority: 'Priority (Requests)'.High,

            // Choice from a dropdown whose Items = Choices('Priority (Requests)')
            Status: ddStatus.Selected.Value,

            // Choices (multi-select): a table of enum values
            Channels: cmbChannels.SelectedItems,

            // Yes/No is an enum too
            'Is Urgent': If(tglUrgent.Value, 'Is Urgent (Requests)'.Yes, 'Is Urgent (Requests)'.No)
        }
    ),
    Notify("Save failed: " & FirstError.Message, NotificationType.Error),
    Notify("Saved.", NotificationType.Success)
);

