        IsBlank(txtSearch.Text) ||
            StartsWith(Name, txtSearch.Text) ||
            StartsWith('Requester Email', txtSearch.Text),
        // Choice filter
        IsBlank(ddStatus.Selected.Value) || Status = ddStatus.Selected.Value,
        // Lookup filter: compare the lookup's primary key
