            Customer.Account = cmbCustomer.Selected.Account,
        // Date range
        'Created On' >= dpFrom.SelectedDate,
        'Created On' < DateAdd(dpTo.SelectedDate, 1, TimeUnit.Days)
    ),
    "createdon",
    SortOrder.Descending
)

