// 3. Wrapper that adds the anti-forgery token
(function (webapi, $) {
  function safeAjax(ajaxOptions) {
    var deferredAjax = $.Deferred();
    shell.getTokenDeferred().done(function (token) {
      if (!ajaxOptions.headers) {
        $.extend(ajaxOptions, { headers: { __RequestVerificationToken: token } });
      } else {
        ajaxOptions.headers["__RequestVerificationToken"] = token;
      }
      $.ajax(ajaxOptions)
        .done(function (data, textStatus, jqXHR) {
          validateLoginSession(data, textStatus, jqXHR, deferredAjax.resolve);
        })
        .fail(deferredAjax.reject);
    }).fail(function () {
      deferredAjax.rejectWith(this, arguments);
    });
    return deferredAjax.promise();
  }
  webapi.safeAjax = safeAjax;
})((window.webapi = window.webapi || {}), jQuery);

// 4. Create a row. The URL uses the table's entity set name (plural).
webapi.safeAjax({
  type: "POST",
  url: "/_api/bv_requests",
  contentType: "application/json",
  data: JSON.stringify({
    bv_name: $("#title").val(),
    bv_details: $("#details").val(),
    "bv_Category@odata.bind": "/bv_categories(" + $("#category").val() + ")"
  }),
  success: function (res, status, xhr) {
    var newId = xhr.getResponseHeader("entityid");
    window.location.href = "/request-detail/?id=" + newId;
  },
  error: function (xhr) {
    console.error(xhr.responseText);
  }
});

